"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9311],{59311:e=>{e.exports=JSON.parse('{"slug":"eksport-dizelya-oktyabr-2026-dempfer-ceny","locale":"zh","title":"俄罗斯部分恢复柴油出口，冬季柴油交易所价格却创新高","description":"俄罗斯从2026年十月10日起部分开放柴油出口，首阶段500千吨。解释价格补贴机制及国内柴油价格风险。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年十月9日，美国财政部发出许可证，允许俄罗斯柴油交易持续至2027年四月7日。俄罗斯政府从十月10日起部分解除七月以来覆盖所有生产商的出口禁令。首阶段500千吨，须获政府同意并按配额出口，约为禁令前管道月出口的29%。汽油出口禁令仍持续至2027年一月31日。"},{"id":"b002","kind":"paragraph","text":"全球柴油供应不足。国际能源署十月14日估计，九月全球柴油出口同比少700千桶/日；俄罗斯与中东合计少1.3百万桶/日，其他供应商只补上部分。库存预计不早于2027年下半年恢复。俄罗斯500千吨约3.7百万桶，不到全球月消费的1%。即使特朗普提及的全部4.8百万吨，全球也只需略多于1天就会消耗，难显著推动全球价格。"},{"id":"b003","kind":"paragraph","text":"俄罗斯国内柴油更便宜。九月出口价每吨147 268卢布，国内批发67.73千。补贴按假定国内价58 950卢布而非真实价格计算。设想农民可59卢布卖奶给邻居，或147卖到城里；村委为留住牛奶补贴部分差额。燃料同理：预算补偿65%价差，约每吨57千卢布，称为燃料价格补偿机制。九月支付305.5十亿卢布，为2022年四月以来最多；加上其他抵扣，石油企业收回418.5十亿，占全部油气税款48%。"},{"id":"b004","kind":"paragraph","text":"补贴有门槛：柴油月均批发价超过每吨76.63千卢布时，补贴归零。看的是月均而非单日跳涨：八月均价75.07千，九月降至67.73千。但冬季柴油十月8日创81.8千新高。拟出口的是国内过剩的夏季柴油，上涨的却是寒冬前短缺的冬季品种。没有补贴时出口更划算，因此当局讨论暂停归零规则。副总理诺瓦克表示出口不会影响俄罗斯消费者。"},{"id":"b005","kind":"paragraph","text":"出口对预算有利。财政部长安东\xb7西卢安诺夫预计石油企业收入将支持国际收支，预算获得利润税。每出口一吨，就无需支付国内价格补贴。"},{"id":"b006","kind":"paragraph","text":"配额较小且补贴仍支付时，加油站几乎感受不到出口影响，预算却继续补贴企业，而九月补贴几乎占油气税一半。对司机更差的情况是月均柴油价越过门槛又没有暂停归零措施：企业会更愿出口，国内柴油可能上涨。"},{"id":"b007","kind":"heading","text":"俄罗斯为何在2026年十月允许柴油出口？"},{"id":"b008","kind":"paragraph","text":"美国财政部十月9日发出许可证，允许交易至2027年四月7日。俄罗斯从十月10日起部分解除出口禁令，首阶段500千吨，按配额并获政府同意。诺瓦克表示国内市场将获充分供应。"},{"id":"b009","kind":"heading","text":"燃料价格补偿机制是什么？"},{"id":"b010","kind":"paragraph","text":"财政补偿石油企业在国内以低于出口可得价格销售燃料。2026年九月柴油补偿出口价约每吨147千卢布与假定国内价约59千之间差额的65%。九月总补偿305.5十亿卢布。"},{"id":"b011","kind":"heading","text":"出口会让俄罗斯柴油涨价吗？"},{"id":"b012","kind":"paragraph","text":"首阶段500千吨规模较小，且有配额。风险在另一处：冬季柴油十月8日创每吨81.8千卢布纪录，高于76.6千门槛。如果全月均价越线，补贴归零，出口更划算，因此当局讨论暂停归零机制。"}],"sources":[{"label":"政府部分解除柴油出口禁令","url":"https://www.tut-news.ru/ekonomika/kabmin-chastichno-snyal-zapret-na-eksport-dizelya"},{"label":"一项宽免措施","url":"https://www.kommersant.ru/doc/9023946"},{"label":"不会挤占国内供应：俄罗斯将向特朗普提供哪种柴油","url":"https://aif.ru/money/economy/ot-sebya-ne-otorvem-kakoe-dizelnoe-toplivo-rossiya-otpravit-trampu"},{"label":"石油企业九月通过稳定燃料价格补贴收回近半税款","url":"https://ru.themoscowtimes.com/2026/10/05/neftyaniki-vsentyabre-poluchili-obratno-pochti-polovinu-svoih-nalogov-vkachestve-subsidii-nasderzhivanie-tsen-natoplivo-a207832"},{"label":"冬季柴油交易所价格创新高","url":"https://finance.mail.ru/article/zimnij-dizel-na-birzhe-obnovil-rekord-69231538/"},{"label":"西卢安诺夫解释俄美柴油交易对俄罗斯的好处","url":"https://lenta.ru/news/2026/10/13/siluanov-ob-yasnil-vygodu-rossii-ot-dizelnoy-sdelki-s-ssha"},{"label":"特朗普与俄罗斯的柴油协议难显著降低燃料价格","url":"https://www.cnbc.com/2026/10/13/trump-putin-zelenskyy-russia-ukraine-diesel-oil-price.html"},{"label":"IEA警告柴油市场紧张将延续至2027年下半年","url":"https://www.cnbc.com/2026/10/14/diesel-deal-oil-price-iea-report.html"}],"sourceBodySha256":"4d6c93f6a2b442a1c062b486b428a7b0cfc11a60a49fbe0f2cc57b3fdc9ff699"}')}}]);